1	-- Migration: Auto-reserve escrow when company hires a worker
2	-- When application status changes to 'hired', automatically reserve escrow
3	-- using the job's budget. If company has insufficient balance, the hire fails.
4	
5	CREATE OR REPLACE FUNCTION auto_reserve_escrow_on_hire()
6	RETURNS TRIGGER
7	LANGUAGE plpgsql
8	SECURITY DEFINER
9	SET search_path = public
10	AS $$
11	DECLARE
12	    v_job_budget DECIMAL;
13	    v_company_id UUID;
14	BEGIN
15	    -- Only trigger when status changes TO 'hired'
16	    IF NEW.status = 'hired' AND (OLD.status IS DISTINCT FROM 'hired') THEN
17	        -- Get job budget and company owner
18	        SELECT budget, company_id INTO v_job_budget, v_company_id
19	        FROM jobs WHERE id = NEW.job_id;
20	
21	        IF NOT FOUND THEN
22	            RAISE EXCEPTION 'Vaga nao encontrada: %', NEW.job_id;
23	        END IF;
24	
25	        IF v_job_budget IS NULL OR v_job_budget <= 0 THEN
26	            RAISE EXCEPTION 'Vaga sem valor definido. Defina o orcamento antes de contratar.';
27	        END IF;
28	
29	        -- Reserve escrow atomically
30	        -- If balance < budget, reserve_escrow raises 'Saldo insuficiente' and the hire is rolled back
31	        PERFORM reserve_escrow(NEW.job_id, v_job_budget, v_company_id);
32	
33	        RAISE NOTICE 'Escrow de R$% reservado automaticamente para job % ao contratar worker %',
34	            v_job_budget, NEW.job_id, NEW.worker_id;
35	    END IF;
36	
37	    RETURN NEW;
38	END;
39	$$;
40	
41	-- Use AFTER UPDATE so it fires after validation trigger (trg_validate_application_update)
42	-- If reserve_escrow fails, the entire transaction rolls back (status stays unchanged)
43	DROP TRIGGER IF EXISTS trg_auto_reserve_escrow_on_hire ON applications;
44	CREATE TRIGGER trg_auto_reserve_escrow_on_hire
45	    AFTER UPDATE ON applications
46	    FOR EACH ROW
47	    EXECUTE FUNCTION auto_reserve_escrow_on_hire();
