1	-- Migration: Fix FORCE RLS blocking service_role and fix trigger owner_id
2	--
3	-- Bug 1: FORCE ROW LEVEL SECURITY blocked service_role from accessing tables
4	--         because REVOKE ALL removed permissions from postgres/service_role.
5	-- Fix: Remove FORCE RLS (regular RLS is sufficient), grant ALL to service_role.
6	--
7	-- Bug 2: Company records created by trigger have owner_id = NULL,
8	--         which violates the RLS INSERT/UPDATE policy (owner_id = auth.uid()).
9	-- Fix: Add fallback RLS policy that also allows id = auth.uid() for companies.
10	
11	-- =============================================
12	-- 1. Remove FORCE RLS (regular RLS still enforced for anon/authenticated)
13	-- =============================================
14	ALTER TABLE workers NO FORCE ROW LEVEL SECURITY;
15	ALTER TABLE companies NO FORCE ROW LEVEL SECURITY;
16	ALTER TABLE applications NO FORCE ROW LEVEL SECURITY;
17	ALTER TABLE jobs NO FORCE ROW LEVEL SECURITY;
18	
19	-- =============================================
20	-- 2. Grant service_role full access (bypasses RLS by default)
21	-- =============================================
22	GRANT ALL ON workers TO service_role;
23	GRANT ALL ON companies TO service_role;
24	GRANT ALL ON jobs TO service_role;
25	GRANT ALL ON applications TO service_role;
26	GRANT ALL ON wallets TO service_role;
27	
28	-- =============================================
29	-- 3. Add fallback UPDATE policy for companies using id = auth.uid()
30	--    This handles records where owner_id is NULL (created by trigger)
31	-- =============================================
32	DO $$ BEGIN
33	  DROP POLICY IF EXISTS "Companies can update own profile by id" ON companies;
34	END $$;
35	
36	CREATE POLICY "Companies can update own profile by id"
37	ON companies FOR UPDATE TO authenticated
38	USING (id = auth.uid())
39	WITH CHECK (id = auth.uid());
40	
41	-- Also add fallback INSERT policy
42	DO $$ BEGIN
43	  DROP POLICY IF EXISTS "Companies can insert own profile by id" ON companies;
44	END $$;
45	
46	CREATE POLICY "Companies can insert own profile by id"
47	ON companies FOR INSERT TO authenticated
48	WITH CHECK (id = auth.uid());
49

1	-- Migration: Recreate ALL financial RPCs + Grant EXECUTE permissions
2	-- These functions were never actually created (migrations were marked applied via repair)
3	-- This migration ensures they exist AND are accessible via PostgREST
4	
5	-- =============================================
6	-- 1. CONSTRAINTS & INDEXES (idempotent)
7	-- =============================================
8	
9	-- Balance non-negative constraint
10	DO $$ BEGIN
11	    ALTER TABLE wallets ADD CONSTRAINT wallets_balance_non_negative CHECK (balance >= 0);
12	EXCEPTION WHEN duplicate_object THEN NULL;
13	END $$;
14	
15	-- One active escrow per job
16	CREATE UNIQUE INDEX IF NOT EXISTS idx_escrow_one_reserved_per_job
17	ON escrow_transactions(job_id) WHERE status = 'reserved';
18	
19	-- Unique reference per wallet (prevents double-processing)
20	CREATE UNIQUE INDEX IF NOT EXISTS idx_wallet_tx_unique_reference
21	ON wallet_transactions(wallet_id, reference_id) WHERE reference_id IS NOT NULL;
22	
23	-- =============================================
24	-- 2. ALL FINANCIAL RPCs
25	-- =============================================
26	
27	-- RPC: Atomic balance update
28	CREATE OR REPLACE FUNCTION update_wallet_balance(
29	    p_wallet_id UUID,
30	    p_amount DECIMAL
31	)
32	RETURNS DECIMAL
33	LANGUAGE plpgsql
34	SECURITY DEFINER
35	AS $$
36	DECLARE
37	    v_new_balance DECIMAL;
38	BEGIN
39	    UPDATE wallets
40	    SET balance = balance + p_amount, updated_at = NOW()
41	    WHERE id = p_wallet_id
42	    RETURNING balance INTO v_new_balance;
43	
44	    IF NOT FOUND THEN
45	        RAISE EXCEPTION 'Wallet not found: %', p_wallet_id;
46	    END IF;
47	
48	    RETURN v_new_balance;
49	END;
50	$$;
51	
52	-- RPC: Atomic credit deposit (webhook idempotency)
53	CREATE OR REPLACE FUNCTION credit_deposit(
54	    p_user_id UUID,
55	    p_amount DECIMAL,
56	    p_payment_id TEXT,
57	    p_description TEXT DEFAULT 'Deposito via Pix'
58	)
59	RETURNS BOOLEAN
60	LANGUAGE plpgsql
61	SECURITY DEFINER
62	AS $$
63	DECLARE
64	    v_wallet_id UUID;
65	BEGIN
66	    SELECT id INTO v_wallet_id FROM wallets WHERE user_id = p_user_id;
67	    IF NOT FOUND THEN
68	        RAISE EXCEPTION 'Wallet not found for user: %', p_user_id;
69	    END IF;
70	
71	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
72	    VALUES (v_wallet_id, p_amount, 'credit', p_description, p_payment_id)
73	    ON CONFLICT (wallet_id, reference_id) WHERE reference_id IS NOT NULL
74	    DO NOTHING;
75	
76	    IF NOT FOUND THEN
77	        RETURN FALSE;
78	    END IF;
79	
80	    UPDATE wallets
81	    SET balance = balance + p_amount, updated_at = NOW()
82	    WHERE id = v_wallet_id;
83	
84	    RETURN TRUE;
85	END;
86	$$;
87	
88	-- RPC: Atomic escrow reserve
89	CREATE OR REPLACE FUNCTION reserve_escrow(
90	    p_job_id UUID,
91	    p_amount DECIMAL,
92	    p_company_user_id UUID
93	)
94	RETURNS UUID
95	LANGUAGE plpgsql
96	SECURITY DEFINER
97	AS $$
98	DECLARE
99	    v_wallet_id UUID;
100	    v_balance DECIMAL;
101	    v_escrow_id UUID;
102	BEGIN
103	    SELECT id, balance INTO v_wallet_id, v_balance
104	    FROM wallets WHERE user_id = p_company_user_id FOR UPDATE;
105	
106	    IF NOT FOUND THEN
107	        RAISE EXCEPTION 'Carteira nao encontrada para usuario: %', p_company_user_id;
108	    END IF;
109	
110	    IF v_balance < p_amount THEN
111	        RAISE EXCEPTION 'Saldo insuficiente. Disponivel: %, Necessario: %', v_balance, p_amount;
112	    END IF;
113	
114	    UPDATE wallets
115	    SET balance = balance - p_amount, updated_at = NOW()
116	    WHERE id = v_wallet_id;
117	
118	    INSERT INTO escrow_transactions(job_id, amount, company_wallet_id, status)
119	    VALUES (p_job_id, p_amount, v_wallet_id, 'reserved')
120	    RETURNING id INTO v_escrow_id;
121	
122	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
123	    VALUES (v_wallet_id, -p_amount, 'escrow_reserve', 'Valor reservado para vaga', p_job_id::TEXT);
124	
125	    RETURN v_escrow_id;
126	END;
127	$$;
128	
129	-- RPC: Atomic escrow release
130	CREATE OR REPLACE FUNCTION release_escrow(
131	    p_job_id UUID,
132	    p_worker_wallet_id UUID
133	)
134	RETURNS TABLE(escrow_id UUID, escrow_amount DECIMAL)
135	LANGUAGE plpgsql
136	SECURITY DEFINER
137	AS $$
138	DECLARE
139	    v_escrow_id UUID;
140	    v_amount DECIMAL;
141	BEGIN
142	    UPDATE escrow_transactions
143	    SET status = 'released', released_at = NOW(), worker_wallet_id = p_worker_wallet_id
144	    WHERE job_id = p_job_id AND status = 'reserved'
145	    RETURNING id, amount INTO v_escrow_id, v_amount;
146	
147	    IF NOT FOUND THEN
148	        RAISE EXCEPTION 'No reserved escrow found for job: %', p_job_id;
149	    END IF;
150	
151	    UPDATE wallets
152	    SET balance = balance + v_amount, updated_at = NOW()
153	    WHERE id = p_worker_wallet_id;
154	
155	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
156	    VALUES (p_worker_wallet_id, v_amount, 'escrow_release', 'Pagamento recebido pela vaga', p_job_id::TEXT);
157	
158	    RETURN QUERY SELECT v_escrow_id, v_amount;
159	END;
160	$$;
161	
162	-- RPC: Atomic escrow refund
163	CREATE OR REPLACE FUNCTION refund_escrow(
164	    p_job_id UUID,
165	    p_reason TEXT DEFAULT 'Reembolso de vaga cancelada'
166	)
167	RETURNS TABLE(escrow_id UUID, escrow_amount DECIMAL)
168	LANGUAGE plpgsql
169	SECURITY DEFINER
170	AS $$
171	DECLARE
172	    v_escrow_id UUID;
173	    v_amount DECIMAL;
174	    v_company_wallet_id UUID;
175	BEGIN
176	    UPDATE escrow_transactions
177	    SET status = 'refunded'
178	    WHERE job_id = p_job_id AND status = 'reserved'
179	    RETURNING id, amount, company_wallet_id INTO v_escrow_id, v_amount, v_company_wallet_id;
180	
181	    IF NOT FOUND THEN
182	        RAISE EXCEPTION 'No reserved escrow found for job: %', p_job_id;
183	    END IF;
184	
185	    UPDATE wallets
186	    SET balance = balance + v_amount, updated_at = NOW()
187	    WHERE id = v_company_wallet_id;
188	
189	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
190	    VALUES (v_company_wallet_id, v_amount, 'credit', p_reason, 'refund-' || p_job_id::TEXT);
191	
192	    RETURN QUERY SELECT v_escrow_id, v_amount;
193	END;
194	$$;
195	
196	-- =============================================
197	-- 3. GRANT EXECUTE to PostgREST roles
198	-- =============================================
199	GRANT EXECUTE ON FUNCTION credit_deposit(UUID, DECIMAL, TEXT, TEXT) TO service_role, authenticated;
200	GRANT EXECUTE ON FUNCTION update_wallet_balance(UUID, DECIMAL) TO service_role, authenticated;
201	GRANT EXECUTE ON FUNCTION reserve_escrow(UUID, DECIMAL, UUID) TO service_role, authenticated;
202	GRANT EXECUTE ON FUNCTION release_escrow(UUID, UUID) TO service_role, authenticated;
203	GRANT EXECUTE ON FUNCTION refund_escrow(UUID, TEXT) TO service_role, authenticated;
204

