8	    if (req.method === 'OPTIONS') {
9	        return new Response('ok', { headers: corsHeaders });
10	    }
11	
12	    try {
13	        const supabaseAdmin = createClient(
14	            Deno.env.get('SUPABASE_URL') ?? '',
15	            Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
16	        );
17	
18	        const authHeader = req.headers.get('Authorization');
19	        if (!authHeader) throw new Error('Missing Authorization header');
20	        const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(authHeader.replace('Bearer ', ''));
21	        if (userError || !user) throw new Error('Invalid Token');
22	
23	        if (isRateLimited(user.id, 'checkout', 5, 60_000)) {
24	            return new Response(JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }), {
25	                headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429
26	            });
27	        }
28	
29	        const { jobId, workerId } = await req.json();
30	
31	        if (!jobId || !workerId) {
32	            throw new Error('jobId and workerId are required');
33	        }
34	
35	        // 1. Verify caller is the job owner
36	        const { data: job, error: jobError } = await supabaseAdmin
37	            .from('jobs')
38	            .select('company_id')
39	            .eq('id', jobId)
40	            .single();
41	
42	        if (jobError || !job) throw new Error('Job not found');
43	        if (job.company_id !== user.id) throw new Error('Not authorized');
44	
45	        // 2. Verify workerId has a completed application (or confirmed checkout) for this job
46	        const { data: app, error: appError } = await supabaseAdmin
47	            .from('applications')
48	            .select('worker_id, status, company_checkout_confirmed_at')
49	            .eq('job_id', jobId)
50	            .eq('worker_id', workerId)
51	            .in('status', ['in_progress', 'completed'])
52	            .single();
53	
54	        if (appError || !app) {
55	            throw new Error('Candidatura nao encontrada ou trabalho ainda nao foi iniciado');
56	        }
57	
58	        // Only allow release if job is completed OR company explicitly confirmed checkout
59	        if (app.status !== 'completed' && !app.company_checkout_confirmed_at) {
60	            throw new Error('O trabalho precisa estar concluido antes de liberar o pagamento');
61	        }
62	
63	        // Get or create worker wallet
64	        let { data: workerWallet } = await supabaseAdmin
65	            .from('wallets')
66	            .select('id')
67	            .eq('user_id', workerId)
68	            .single();
69	
70	        if (!workerWallet) {
71	            // Auto-create wallet for worker if missing (legacy users)
72	            const { data: newWallet, error: createError } = await supabaseAdmin
73	                .from('wallets')
74	                .insert({ user_id: workerId, balance: 0, user_type: 'worker' })
75	                .select('id')
